// DNS Lookup using Google DNS-over-HTTPS (no API key required)
// Queries multiple record types and returns a structured result.

const input = $input.item.json;
const domain = input.params?.domain ?? input.arguments?.domain ?? input.params?.domain_name ?? input.arguments?.domain_name;

if (!domain) {
  throw new Error('Missing required parameter: domain');
}

const recordTypes = ['A', 'AAAA', 'MX', 'NS', 'TXT', 'CNAME', 'SOA'];
const dnsResults = {};

for (const type of recordTypes) {
  try {
    const response = await fetch(
      `https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=${type}`,
      { headers: { Accept: 'application/dns-json' } }
    );
    if (!response.ok) continue;
    const data = await response.json();
    if (data.Answer && data.Answer.length > 0) {
      dnsResults[type] = data.Answer.map(record => ({
        name: record.name,
        ttl: record.TTL,
        data: record.data
      }));
    }
  } catch (err) {
    dnsResults[type] = { error: err.message };
  }
}

const foundTypes = Object.keys(dnsResults);

return {
  json: {
    tool: 'dns_lookup',
    domain,
    records_found: foundTypes,
    dns_records: dnsResults,
    summary: foundTypes.length > 0
      ? `DNS lookup for "${domain}" returned ${foundTypes.length} record type(s): ${foundTypes.join(', ')}.`
      : `DNS lookup for "${domain}" returned no records.`
  }
};

// Format the RDAP (Registration Data Access Protocol) response into a clean WHOIS summary.
// RDAP is the modern successor to WHOIS, provided free by rdap.org.

const rdap = $input.item.json;

// Helper: extract first fn (formatted name) from a vCard array
const getVCardFn = (vcard) => {
  if (!vcard || !Array.isArray(vcard[1])) return undefined;
  const fn = vcard[1].find(v => v[0] === 'fn');
  return fn ? fn[3] : undefined;
};

// Parse events into a key/date map
const events = (rdap.events ?? []).reduce((acc, e) => {
  acc[e.eventAction] = e.eventDate;
  return acc;
}, {});

// Extract entity names by role
const getEntityByRole = (role) => {
  const entity = (rdap.entities ?? []).find(e => e.roles?.includes(role));
  if (!entity) return null;
  const name = entity.handle ?? getVCardFn(entity.vcardArray);
  return name ?? null;
};

const domain = rdap.ldhName ?? rdap.handle ?? 'unknown';

const result = {
  tool: 'whois_lookup',
  domain,
  status: rdap.status ?? [],
  registrar: getEntityByRole('registrar'),
  registrant: getEntityByRole('registrant'),
  nameservers: (rdap.nameservers ?? []).map(ns => ns.ldhName ?? ns.handle),
  dates: {
    registered: events['registration'] ?? null,
    last_changed: events['last changed'] ?? null,
    expires: events['expiration'] ?? null,
    last_update_of_rdap_database: events['last update of RDAP database'] ?? null
  },
  port43: rdap.port43 ?? null,
  rdap_links: (rdap.links ?? []).map(l => ({ rel: l.rel, href: l.href })),
  summary: `WHOIS/RDAP lookup for "${domain}" completed. Status: ${(rdap.status ?? []).join(', ') || 'N/A'}. Registrar: ${getEntityByRole('registrar') ?? 'N/A'}.`
};

return { json: result };
